from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import UeProcedureError
from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall


class RtgDataTransfer(LteDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, alias, dt_definition, configuration, rpc_socket, _ue_id, logger_name='ute_ue'):
        """
        Basic initialization.

        :param alias: Alias to be assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        """
        self._ue_id = _ue_id
        self._transfer_id = None
        super(RtgDataTransfer, self).__init__(alias, dt_definition, configuration, logger_name)
        self.name = alias
        self.rpc_call = RpcCall(rpc_socket, self.logger).call
        self.proto_details = {'packet_size': 200, 'packet_rate': None}

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        self._check_protocol_details(self._dt_definition.protocol_details)
        params_dict = {"ue_id": self._ue_id,
                       "bearer_id": self._dt_definition.bearer.get_bearer_id(),     # integer
                       "direction": self._dt_definition.direction,                  # 'ul', 'dl' or 'simultaneous_ul_dl'
                       "duration": self._dt_definition.duration,                    # in seconds
                       "throughput": self._dt_definition.throughput,                # in Kbits/s
                       "protocol": self._dt_definition.protocol,                    # e.g. 'udp'
                       "packet_size": self.proto_details['packet_size'],            # in bytes, default is 200
                       "packet_rate": self.proto_details['packet_rate']             # if set, throughput is ignored
                       }

        if params_dict['direction'] == 'simultaneous_ul_dl':
            params_dict['throughput'] = {'ul': self._dt_definition.ul_throughput, 'dl': self._dt_definition.dl_throughput}

        self._transfer_id = self.rpc_call(method="start_data_transfer", params=params_dict,
                                          log_msg="UE({0}) - Starting data transfer".format(self._ue_id))

    def _check_protocol_details(self, protocol_details):
        for key, value in protocol_details.items():
            if key == 'packet_size':
                self.proto_details.update({'packet_size': self._verify_packet_size(value)})
            elif key == 'packet_rate':
                self.proto_details.update({'packet_rate': self._verify_packet_rate(value)})
                self.logger.warning("packet_rate parameter has been set for data transfer {} this will ignore throughput parameter!".
                                    format(self.name))
            else:
                raise ValueError('Unknown parameter {}.'.format(key))

    def _verify_packet_size(self, packet_size):
        # TODO check if packet_size range is ok
        if packet_size.isdigit():
            return int(packet_size)
        else:
            raise ValueError('Invalid parameter packet_size.')

    def _verify_packet_rate(self, packet_rate):
        # TODO check if packet_rate range is ok
        try:
            packet_rate = float(packet_rate)
        except ValueError:
            raise ValueError('Invalid parameter packet_rate.')
        else:
            if packet_rate > 0.1:
                return float(packet_rate)
            else:
                raise ValueError('Parameter packet_rate should be a value higher than 0.1')

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        if self._transfer_id is None:
            raise UeProcedureError("Stopping data transfer failed for UE({}), data transfer hasn't been started yet".format(self._ue_id))
        else:
            params_dict = {"transfer_id": self._transfer_id}
            self.rpc_call(method="stop_data_transfer", params=params_dict, log_msg="UE({0}) - Stopping data transfer".format(self._ue_id))

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        if self._transfer_id is None:
            return False
        else:
            params_dict = {"transfer_id": self._transfer_id}
            response = self.rpc_call(method="is_traffic_running",
                                     params=params_dict,
                                     log_msg="UE({0}) - Checking whether data transfer is running".format(self._ue_id))
            return response

    def get_average_throughput(self, omit=0):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()' if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        if omit:
            raise TypeError("Parameter 'omit' is currently not supported by ta_ue_plugin_rtg")
        if self._transfer_id is None:
            raise UeProcedureError("Getting average throughput failed for UE({}), data transfer hasn't been started yet".format(self._ue_id))
        else:
            params_dict = {"transfer_id": self._transfer_id}

            avg_tput = self.rpc_call(method="get_average_throughput", params=params_dict,
                                     log_msg="UE({0}) - Getting average throughput".format(self._ue_id))
            tput = None
            dl_avg_tput = float(avg_tput[0]) / 1000
            ul_avg_tput = float(avg_tput[1]) / 1000
            if self._dt_definition.direction == 'ul':
                tput = ul_avg_tput
            elif self._dt_definition.direction == 'dl':
                tput = dl_avg_tput
            elif self._dt_definition.direction == 'simultaneous_ul_dl':
                tput = ul_avg_tput + dl_avg_tput
            self.logger.info("Average throughput equals {} kbps".format(tput))
            return tput

    def await_finish(self):
        """
        Wait until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        if self._transfer_id is None:
            raise UeProcedureError("Await data transfer finish failed for UE({}), data transfer hasn't been started yet".format(self._ue_id))
        else:
            if not self.is_running():
                return
            else:
                params_dict = {"transfer_id": self._transfer_id}
                # TODO max waiting time is 10 minutes (timeout on tcp socket)
                self.rpc_call(method="await_traffic_finish", params=params_dict,
                              log_msg="UE({0}) - Awaiting data transfer finish ".format(self._ue_id))

    def check_data_transfer(self):
        """
        Check if data transfer client and server output is progressing.
        :return:
        """
        raise NotImplementedError

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If reset data transfer statistics failed
        """
        pass

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        if self._transfer_id is None:
            raise UeProcedureError("Getting datagram loss failed for UE({}), data transfer hasn't been started yet".format(self._ue_id))
        else:
            params_dict = {"transfer_id": self._transfer_id}
            pckt_pass = self.rpc_call(method="get_datagram_loss", params=params_dict, log_msg="UE({0}) - Getting datagram loss".format(self._ue_id))

            dl_pckt_loss = (100 - float(pckt_pass[0]))
            ul_pckt_loss = (100 - float(pckt_pass[1]))
            if self._dt_definition.direction == 'ul':
                return ul_pckt_loss
            elif self._dt_definition.direction == 'dl':
                return dl_pckt_loss
            elif self._dt_definition.direction == 'simultaneous_ul_dl':
                return dl_pckt_loss + ul_pckt_loss
